import{_ as s,o as t,c as i,a2 as n}from"./chunks/framework.BXzK3EA4.js";const g=JSON.parse('{"title":"HTTP/1.1 队头阻塞与绕行手段","description":"这一篇只讲 HTTP/1.1 自己的问题,以及浏览器在协议层解决之前怎么绕。 相邻专题: - 演进全景(为什么会有这一堆 workaround)→ HTTP 协议演进 - HTTP/2 如何把 workaround 收回协议层 → HT","frontmatter":{},"headers":[],"relativePath":"网络/3-http1-problems.md","filePath":"网络/3-http1-problems.md","lastUpdated":1793545253000}'),e={name:"网络/3-http1-problems.md"};function l(p,a,h,r,o,d){return t(),i("div",null,[...a[0]||(a[0]=[n(`<h1 id="http-1-1-队头阻塞与绕行手段" tabindex="-1">HTTP/1.1 队头阻塞与绕行手段 <a class="header-anchor" href="#http-1-1-队头阻塞与绕行手段" aria-label="Permalink to &quot;HTTP/1.1 队头阻塞与绕行手段&quot;">​</a></h1><blockquote><p><strong>这一篇只讲 HTTP/1.1 自己的问题</strong>,以及浏览器在协议层解决之前<strong>怎么绕</strong>。</p><p>相邻专题:</p><ul><li>演进全景(为什么会有这一堆 workaround)→ <a href="./2-http-evolution">HTTP 协议演进</a></li><li>HTTP/2 如何把 workaround 收回协议层 → <a href="./4-http2">HTTP/2 机制:分帧、多路复用与 HPACK</a></li><li>HTTP/3 如何解决传输层队头阻塞 → <a href="./13-http3">HTTP/3 与 QUIC 深度</a></li></ul></blockquote><h2 id="一、什么是队头阻塞" tabindex="-1">一、什么是队头阻塞 <a class="header-anchor" href="#一、什么是队头阻塞" aria-label="Permalink to &quot;一、什么是队头阻塞&quot;">​</a></h2><p><strong>队头阻塞</strong>(Head-of-Line Blocking, HoL Blocking)是 HTTP/1.1 最核心的性能问题。</p><h3 id="_1-1-直观例子" tabindex="-1">1.1 直观例子 <a class="header-anchor" href="#_1-1-直观例子" aria-label="Permalink to &quot;1.1 直观例子&quot;">​</a></h3><p>想象超市结账:</p><ul><li>一条队 5 个人,最前面的人在算 100 件商品</li><li>后面 4 个人都得等,即使他们只要付 1 件</li></ul><p>HTTP/1.1 一个连接(一个「队」)上:</p><ul><li>请求 1 慢,后面的请求都得等</li></ul><h3 id="_1-2-http-1-1-连接特性" tabindex="-1">1.2 HTTP/1.1 连接特性 <a class="header-anchor" href="#_1-2-http-1-1-连接特性" aria-label="Permalink to &quot;1.2 HTTP/1.1 连接特性&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>HTTP/1.1 默认 Keep-Alive:</span></span>
<span class="line"><span>- 一个 TCP 连接可以发多个请求</span></span>
<span class="line"><span>- 但响应必须按请求顺序返回(FIFO)</span></span>
<span class="line"><span>- 一个慢响应阻塞所有后续响应</span></span></code></pre></div><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>客户端                         服务端</span></span>
<span class="line"><span>  |  请求 1 (慢)              |</span></span>
<span class="line"><span>  |  ─────────────────────→  |</span></span>
<span class="line"><span>  |                           |  处理 1 用 1s</span></span>
<span class="line"><span>  |  请求 2 (快)             |</span></span>
<span class="line"><span>  |  ←─── 等待中... ────────  |</span></span>
<span class="line"><span>  |                           |  处理 2 只要 0.1s</span></span>
<span class="line"><span>  |  ←───── 响应 1 终于回来 ──|</span></span>
<span class="line"><span>  |  请求 2 现在才发出去 ────→|</span></span>
<span class="line"><span>  |  ←───── 响应 2 立刻回来 ──|</span></span></code></pre></div><p><strong>响应 2 本来 100ms 就能返回,实际等了 1000ms+。</strong></p><h2 id="二、为什么会这样" tabindex="-1">二、为什么会这样 <a class="header-anchor" href="#二、为什么会这样" aria-label="Permalink to &quot;二、为什么会这样&quot;">​</a></h2><h3 id="_2-1-设计原因" tabindex="-1">2.1 设计原因 <a class="header-anchor" href="#_2-1-设计原因" aria-label="Permalink to &quot;2.1 设计原因&quot;">​</a></h3><p>HTTP/1.x 是<strong>文本协议 + 顺序解析</strong>:</p><ul><li>浏览器通过<strong>响应顺序</strong>判断哪个响应对应哪个请求</li><li>乱序返回会导致解析混乱</li><li>解决方案简单粗暴:<strong>严格顺序</strong></li></ul><h3 id="_2-2-不支持多路复用的后果" tabindex="-1">2.2 不支持多路复用的后果 <a class="header-anchor" href="#_2-2-不支持多路复用的后果" aria-label="Permalink to &quot;2.2 不支持多路复用的后果&quot;">​</a></h3><p>浏览器对同一域名最多开 <strong>6 个并发连接</strong>:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>连接 1: 请求 A → 等响应 A</span></span>
<span class="line"><span>连接 2: 请求 B → 等响应 B</span></span>
<span class="line"><span>连接 3: 请求 C → 等响应 C</span></span>
<span class="line"><span>连接 4: 请求 D → 等响应 D</span></span>
<span class="line"><span>连接 5: 请求 E → 等响应 E</span></span>
<span class="line"><span>连接 6: 请求 F → 等响应 F</span></span>
<span class="line"><span></span></span>
<span class="line"><span>第 7 个请求?排队等前面完成。</span></span></code></pre></div><p>实际项目:一个 HTML 引用 30 个 JS/CSS,前 6 个并发,后面 24 个排队。</p><h3 id="_2-3-两个层次的队头阻塞" tabindex="-1">2.3 两个层次的队头阻塞 <a class="header-anchor" href="#_2-3-两个层次的队头阻塞" aria-label="Permalink to &quot;2.3 两个层次的队头阻塞&quot;">​</a></h3><p>这是本篇最核心的概念,后面 HTTP/2 与 HTTP/3 的所有差异都从这里展开:</p><table tabindex="0"><thead><tr><th>层次</th><th>发生在哪</th><th>表现</th><th>谁能解决</th></tr></thead><tbody><tr><td><strong>应用层(HTTP 层)</strong></td><td>HTTP/1.1 的响应必须按序返回</td><td>一个慢接口堵住后面所有请求</td><td>HTTP/2 多路复用</td></tr><tr><td><strong>传输层(TCP 层)</strong></td><td>TCP 是字节流,必须顺序交付</td><td>丢一个包,连接上所有数据都得等重传</td><td>HTTP/3 的 QUIC</td></tr></tbody></table><p><strong>应用层</strong>:HTTP/1.1 的协议设计就要求顺序返回,慢请求无法绕过。</p><p><strong>传输层</strong>:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>TCP 是字节流:</span></span>
<span class="line"><span>- 包 1、2、3、4、5 顺序发送</span></span>
<span class="line"><span>- 包 3 丢失 → 接收方等待包 3 重传</span></span>
<span class="line"><span>- 包 4、5 已经在接收方缓存,但不能交给应用层(TCP 是顺序的)</span></span>
<span class="line"><span>- 所有数据都阻塞,直到包 3 到达</span></span></code></pre></div><p><strong>关键</strong>:HTTP/2 的多路复用让<strong>应用层</strong>的流可以并行,但底层 TCP 仍是串行的——流 A 的包丢了,流 B、C、D 全部要等。<strong>这就是 HTTP/2 解决了一半、HTTP/3 才彻底解决的原因。</strong></p><h2 id="三、http-1-1-时代的绕行手段" tabindex="-1">三、HTTP/1.1 时代的绕行手段 <a class="header-anchor" href="#三、http-1-1-时代的绕行手段" aria-label="Permalink to &quot;三、HTTP/1.1 时代的绕行手段&quot;">​</a></h2><p>HTTP/1.1 没有真正的解法,浏览器和工程上只能<strong>绕</strong>。以下五种是历史上真实用过的办法,每一种都有代价。</p><h3 id="_3-1-多连接" tabindex="-1">3.1 多连接 <a class="header-anchor" href="#_3-1-多连接" aria-label="Permalink to &quot;3.1 多连接&quot;">​</a></h3><p>浏览器对同域名最多 6 个并发连接(Chrome 实际就是 6)。</p><p><strong>代价</strong>:增加 TCP + TLS 握手成本;而且 6 条对现代页面(30+ 资源)根本不够。</p><h3 id="_3-2-域名分片-domain-sharding" tabindex="-1">3.2 域名分片(Domain Sharding) <a class="header-anchor" href="#_3-2-域名分片-domain-sharding" aria-label="Permalink to &quot;3.2 域名分片(Domain Sharding)&quot;">​</a></h3><p>把资源分散到多个子域,每个子域各享 6 条连接:</p><div class="language-html vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">html</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">&lt;!-- 主域:example.com --&gt;</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">&lt;!-- 分片:static1.example.com、static2.example.com --&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">link</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> rel</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;stylesheet&quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> href</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;https://static1.example.com/a.css&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">link</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> rel</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;stylesheet&quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> href</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;https://static2.example.com/b.css&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span></code></pre></div><p><strong>效果</strong>:<code>6 连接 × 3 子域 = 18 并发</code>。</p><p><strong>代价</strong>:增加 DNS 查询与握手;<strong>HTTP/2 时代必须禁用</strong>(多路复用已经解决并发问题,分片反而浪费连接)。</p><h3 id="_3-3-资源合并" tabindex="-1">3.3 资源合并 <a class="header-anchor" href="#_3-3-资源合并" aria-label="Permalink to &quot;3.3 资源合并&quot;">​</a></h3><p>把多个小资源合并成一个大资源,减少请求数:</p><ul><li><strong>雪碧图(CSS Sprite)</strong>:多个小图标合并成一张大图,<code>background-position</code> 定位</li><li><strong>合并 JS / CSS</strong>:一个大 bundle 而不是多个小文件</li></ul><p><strong>代价</strong>:维护差(改一个图标要重出整张 sprite)、缓存粒度大(改一行 JS 整个 bundle 失效)。</p><p><strong>HTTP/2 时代必须禁用</strong>:请求数不再是瓶颈,大 bundle 反而拖慢首屏。</p><h3 id="_3-4-内联资源" tabindex="-1">3.4 内联资源 <a class="header-anchor" href="#_3-4-内联资源" aria-label="Permalink to &quot;3.4 内联资源&quot;">​</a></h3><div class="language-html vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">html</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">style</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">body</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">background</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">red</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">; }&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">style</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">script</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;console.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">log</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;inline&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">script</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span></code></pre></div><p><strong>代价</strong>:HTML 体积大、不能单独缓存、阻塞关键路径。</p><p><strong>HTTP/2 时代少用</strong>:头部压缩已经让重复头几乎不花钱,而内联牺牲了缓存能力。</p><h3 id="_3-5-preload-prefetch" tabindex="-1">3.5 preload / prefetch <a class="header-anchor" href="#_3-5-preload-prefetch" aria-label="Permalink to &quot;3.5 preload / prefetch&quot;">​</a></h3><div class="language-html vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">html</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">&lt;!-- preload:高优先级,提前加载当前页面关键资源 --&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">link</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> rel</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;preload&quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> href</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;/critical.css&quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> as</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;style&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">&lt;!-- prefetch:低优先级,提前加载下个路由的资源 --&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">link</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> rel</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;prefetch&quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> href</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;/next-page.js&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span></code></pre></div><p><strong>优点</strong>:不改变资源结构,只是提前加载,<strong>在 HTTP/2 时代依然是推荐做法</strong>(替代被废弃的 Server Push)。</p><h3 id="_3-6-五种手段的共同点" tabindex="-1">3.6 五种手段的共同点 <a class="header-anchor" href="#_3-6-五种手段的共同点" aria-label="Permalink to &quot;3.6 五种手段的共同点&quot;">​</a></h3><p>它们本质都在做同一件事:<strong>减少请求数或增加并发数</strong>,而不是<strong>让一条连接真正并行</strong>。所以:</p><ul><li>每个手段都有代价(握手、缓存粒度、维护成本)</li><li>都不是协议层的解决方案</li><li>HTTP/2 一出来,大部分就该被废弃了</li></ul><h2 id="四、http-2-如何把这个-workaround-收回协议层" tabindex="-1">四、HTTP/2 如何把这个 workaround 收回协议层 <a class="header-anchor" href="#四、http-2-如何把这个-workaround-收回协议层" aria-label="Permalink to &quot;四、HTTP/2 如何把这个 workaround 收回协议层&quot;">​</a></h2><p>HTTP/2 不再让浏览器去「多开连接」,而是让<strong>一条连接内部并行</strong>:</p><ul><li>一个 TCP 连接,多个<strong>流(stream)</strong>,每个流有独立 ID</li><li>请求和响应都拆成<strong>帧(Frame)</strong>,帧带流 ID</li><li>帧可以乱序发送和接收,接收方按流 ID 重组</li><li><strong>不再有「队」的概念</strong></li></ul><p>一句话:<strong>一个连接、多条流、乱序发送、按流 ID 重组</strong>,不再有「队」的概念。</p><p>机制细节(帧结构与帧类型、流状态机、两级流控、HPACK)见 <a href="./4-http2">HTTP/2 机制:分帧、多路复用与 HPACK</a>。</p><p><strong>注意</strong>:HTTP/2 <strong>只解决了应用层队头阻塞</strong>,传输层的还在(见 2.3)。</p><h2 id="五、性能对比" tabindex="-1">五、性能对比 <a class="header-anchor" href="#五、性能对比" aria-label="Permalink to &quot;五、性能对比&quot;">​</a></h2><p>以「首屏 30 个资源」为例:</p><table tabindex="0"><thead><tr><th>方案</th><th>并发方式</th><th>耗时</th></tr></thead><tbody><tr><td>HTTP/1.1(6 连接)</td><td>6 个一批,分 5 批</td><td>约 1000ms</td></tr><tr><td>HTTP/2(多路复用)</td><td>1 连接 30 流并行</td><td>约 300~500ms</td></tr><tr><td>HTTP/3(弱网 2% 丢包)</td><td>流独立重传</td><td>约 200~400ms</td></tr></tbody></table><p><strong>弱网下差距最明显</strong>:HTTP/2 的传输层队头阻塞在丢包时会让所有流一起卡住,而 HTTP/3 只重传出问题的那条流。</p><h2 id="六、http-2-时代的实战清单" tabindex="-1">六、HTTP/2 时代的实战清单 <a class="header-anchor" href="#六、http-2-时代的实战清单" aria-label="Permalink to &quot;六、HTTP/2 时代的实战清单&quot;">​</a></h2><h3 id="_6-1-反模式-http-1-1-时代的优化-现在要拆掉" tabindex="-1">6.1 反模式(HTTP/1.1 时代的优化,现在要拆掉) <a class="header-anchor" href="#_6-1-反模式-http-1-1-时代的优化-现在要拆掉" aria-label="Permalink to &quot;6.1 反模式(HTTP/1.1 时代的优化,现在要拆掉)&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>❌ 雪碧图        → 拆成独立图片,配合 HTTP/2 多路复用</span></span>
<span class="line"><span>❌ 域名分片      → 合并到一个域名</span></span>
<span class="line"><span>❌ 内联大段 CSS/JS → 独立文件,长期缓存</span></span>
<span class="line"><span>❌ 合并成超大 bundle → 拆小包,按需加载 + preload 关键 chunk</span></span></code></pre></div><h3 id="_6-2-http-2-时代仍然要做的优化" tabindex="-1">6.2 HTTP/2 时代仍然要做的优化 <a class="header-anchor" href="#_6-2-http-2-时代仍然要做的优化" aria-label="Permalink to &quot;6.2 HTTP/2 时代仍然要做的优化&quot;">​</a></h3><ul><li><strong>压缩</strong>:Brotli 优于 gzip(协商过程见 <a href="./23-content-encoding-alpn">内容压缩与 ALPN</a>)</li><li><strong>缓存</strong>:<code>Cache-Control</code> + <code>ETag</code>(见 <a href="./8-cache">HTTP 缓存机制</a>)</li><li><strong>图片优化</strong>:AVIF / WebP + 显式宽高</li><li><strong>懒加载</strong>:非关键资源延迟加载</li><li><strong>preload</strong>:关键资源显式声明优先级</li><li><strong>CDN</strong>:就近分发,顺带吃到 HTTP/2 与 HTTP/3</li></ul><h3 id="_6-3-启用-http-2" tabindex="-1">6.3 启用 HTTP/2 <a class="header-anchor" href="#_6-3-启用-http-2" aria-label="Permalink to &quot;6.3 启用 HTTP/2&quot;">​</a></h3><p>Nginx 侧加一个 <code>http2</code> 参数即可,应用层无需改动。</p><blockquote><p>完整配置(含 TLS 套件)与验证方法(DevTools Protocol 列、<code>curl -I --http2</code>)见 <a href="./4-http2">HTTP/2 机制:分帧、多路复用与 HPACK</a>。</p></blockquote><h2 id="🎯-面试常考" tabindex="-1">🎯 面试常考 <a class="header-anchor" href="#🎯-面试常考" aria-label="Permalink to &quot;🎯 面试常考&quot;">​</a></h2><h3 id="q1-http-1-1-队头阻塞是什么" tabindex="-1">Q1:HTTP/1.1 队头阻塞是什么? <a class="header-anchor" href="#q1-http-1-1-队头阻塞是什么" aria-label="Permalink to &quot;Q1:HTTP/1.1 队头阻塞是什么?&quot;">​</a></h3><p><strong>答</strong>:HTTP/1.1 一个 TCP 连接上,响应必须按请求顺序返回,前面的慢响应会阻塞后面的响应。</p><h3 id="q2-浏览器为什么最多-6-个并发连接" tabindex="-1">Q2:浏览器为什么最多 6 个并发连接? <a class="header-anchor" href="#q2-浏览器为什么最多-6-个并发连接" aria-label="Permalink to &quot;Q2:浏览器为什么最多 6 个并发连接?&quot;">​</a></h3><p><strong>答</strong>:因为 HTTP/1.1 一条连接有队头阻塞,只能靠多开连接绕开。RFC 2616 建议 2 个,实际浏览器(如 Chrome)用 6 个。</p><h3 id="q3-http-2-怎么解决的" tabindex="-1">Q3:HTTP/2 怎么解决的? <a class="header-anchor" href="#q3-http-2-怎么解决的" aria-label="Permalink to &quot;Q3:HTTP/2 怎么解决的?&quot;">​</a></h3><p><strong>答</strong>:</p><ul><li>单 TCP 连接上多路复用,多个 stream 并行</li><li>请求/响应拆成帧,帧带 stream ID,可以乱序发送</li><li>接收方按 stream ID 重组</li></ul><p>→ 机制细节见 <a href="./4-http2">4-http2</a></p><h3 id="q4-http-2-还有队头阻塞吗" tabindex="-1">Q4:HTTP/2 还有队头阻塞吗? <a class="header-anchor" href="#q4-http-2-还有队头阻塞吗" aria-label="Permalink to &quot;Q4:HTTP/2 还有队头阻塞吗?&quot;">​</a></h3><p><strong>答</strong>:有,但只剩<strong>传输层</strong>。TCP 丢一个段,后面所有字节都得等它重传,所有 stream 一起卡住——哪怕它们的数据本身完好。HTTP/3 / QUIC 用 UDP + 独立流彻底解决。</p><h3 id="q5-既然-http-2-已经解决了并发-为什么还需要-preload" tabindex="-1">Q5:既然 HTTP/2 已经解决了并发,为什么还需要 preload? <a class="header-anchor" href="#q5-既然-http-2-已经解决了并发-为什么还需要-preload" aria-label="Permalink to &quot;Q5:既然 HTTP/2 已经解决了并发,为什么还需要 preload?&quot;">​</a></h3><p><strong>答</strong>:preload 解决的是<strong>优先级</strong>问题,不是并发问题。HTTP/2 的流可以并行,但资源仍然要争抢带宽;用 <code>rel=preload</code> 显式告诉浏览器「这个资源是 LCP,优先给我」,比让浏览器猜更准。它也是 Server Push 被废弃后的替代方案。</p><h2 id="📝-小结" tabindex="-1">📝 小结 <a class="header-anchor" href="#📝-小结" aria-label="Permalink to &quot;📝 小结&quot;">​</a></h2><ul><li>队头阻塞分两层:<strong>应用层</strong>(HTTP/1.1 必须按序返回)与<strong>传输层</strong>(TCP 顺序交付,丢一个包全部要等)。这个区分是整个 HTTP 演进的关键。</li><li>HTTP/1.1 时代的五种绕行手段(多连接、域名分片、资源合并、内联、preload/prefetch)本质都是<strong>减少请求数或增加并发数</strong>,不是协议层解法。</li><li>HTTP/2 用二进制分帧 + 多路复用把 workaround 收回协议层,<strong>但只解决了应用层</strong>;传输层要靠 HTTP/3 的 QUIC。</li><li>性能数据要会讲:同样 30 个资源,HTTP/1.1 约 1000ms,HTTP/2 约 300~500ms,弱网下 HTTP/3 优势最明显。</li><li>HTTP/2 时代要拆掉的反模式:雪碧图、域名分片、内联大段资源、超大 bundle;仍然保留:压缩、缓存、图片优化、懒加载、preload、CDN。</li></ul><h2 id="十、参考文献" tabindex="-1">十、参考文献 <a class="header-anchor" href="#十、参考文献" aria-label="Permalink to &quot;十、参考文献&quot;">​</a></h2><ul><li><a href="https://http2-explained.readthedocs.io/" target="_blank" rel="noreferrer">HTTP/2 详解</a></li><li><a href="https://hpbn.co/" target="_blank" rel="noreferrer">High Performance Browser Networking</a></li><li><a href="https://web.dev/http2/" target="_blank" rel="noreferrer">web.dev HTTP/2</a></li></ul>`,88)])])}const c=s(e,[["render",l]]);export{g as __pageData,c as default};
